function hudCard({ word = 'Incoming call', name, img, number = '', org = null, ring = 'steady' }) {
  const [, c1, c2, c3] = PTHEMES[S.pt];
  const live = S.hudLive, now = Date.now(), id = 'r3c' + (++hudN);
  const anon = !number && /^unknown/i.test(name);
  const call = { id, from: { name, number, img: img || (live ? 'NOFACE' : ''), contactId: null, anon }, to: { userId: 'u1', name: 'V', number: 'WAT-4471', kind: 'player' }, net: NET, mode: 'loud', state: live ? 'live' : 'ringing', startedAt: now - 2300, answeredAt: live ? now - 128000 : null, endedAt: null, outcome: null };
  hudService.calls.set(id, call);
  let html = HUD._callHtml({ call, role: 'callee' }, {});
  // 1. the type's word, while it rings
  if (!live && word !== 'Incoming call') html = html.replaceAll('Incoming call', esc(word));
  // 2. the company, under the name
  if (org) html = html.replace('<span class="ncm-ch-meta">', `<span class="ncm-r3-org">${org.art ? `<img src="${esc(org.art)}" alt="">` : ''}${esc(org.name)}</span><span class="ncm-ch-meta">`);
  // 3. no portrait: the initials and the swirl, inside the real frame
  html = html.replace('<img src="NOFACE" alt="">', `<span class="ncm-ch-ini" aria-hidden="true"><span class="sw"><span class="tr"></span><span class="dot"></span><span class="dot b"></span></span><b>${anon || /^unknown/i.test(name) ? '?' : esc(initials(name))}</b></span>`);
  return `<div class="ncm-call-hud ncm-r3-hud" data-ring="${ring}" style="--ch-ring:${c1};--ch-live:${c2};--ch-key:${c3}">${html}</div>`;
}
