  shared: { tab: 'Phone', nav: 'numbers', view: viewShared, note: '<b>Shared lines.</b> Press Answer on any screen below and the others update. Add or remove people.' },
  term: { tab: 'Terminals', nav: null, view: viewTerm, note: '<b>Configure Terminal.</b> A number, what a caller hears, and which accounts show their owner\'s calls. Untick the mirror on hmori and the Calls folder empties.' },
